property.code:
## Use the current ColorTheme
#template('colorThemeInit.vm')

## Generate reference to background image
#macro(imgURL $name) url($xwiki.getSkinFile("icons/silk/${name}.png")) #end

## Generate reference to background image
#macro(attImgURL $name) url($doc.getAttachmentURL("${name}.png")) #end

/* Settings panel */
.annotationsettings {
  background: $theme.pageContentBackgroundColor; ## $theme.backgroundSecondaryColor;
  border: 1px solid $theme.borderColor;
  border-top: none;
  border-radius: 0 0 10px 10px;
  box-shadow: 0 2px 2px -1px $theme.buttonSecondaryBackgroundColor;
  margin-bottom: -8px;
  padding: 8px 25px; /* Padding left, right = padding of the page content */
  position: relative;
  z-index: 998; /* Right below the submenu. */
}
.floating-menu + .annotationsettings.floating-menu {
  visibility: hidden;
}
.floating-menu:hover + .annotationsettings.floating-menu {
  margin-top: 0;
  visibility: visible;
}
.annotationsettings.floating-menu:hover {
  margin-top: -18px;
  visibility: visible;
}
.annotationsettings.floating-menu:after {
  content: "";
  display: none;
}

.annotationsettings label {
  font-weight: bold;
}
#annotationsdisplay {
  vertical-align: middle;
}

/* Annotations displayed in the text */
.annotation-highlight, .selection-highlight {
  position: relative;
  background-color: var(--mark-bg);
  /* Remove the default mark padding added in bootstrap. 
     The highlights can happen in the middle of words, and it would look odd. */
  padding: 0;
  cursor: pointer;

  &.updated {
    background-color: var(--mark-updated-bg);
  }

  &.altered {
    background-color: var(--mark-altered-bg);
  }

  &.hovered,
  &.hovered .annotation-highlight, &.hovered .selection-highlight {
    /* We want to increase the accent on the element when hovered. 
       The btn warning background color does that without reducing contrast with the default text color too much. 
       We use this class set dynamically in JS instead of pseudo classes because we want highlights to span multiple
       marks across text blocks. */
    /* We repeat the selector because of nested annotation marks. */
    background-color: var(--mark-highlighted-bg);
  }

  .annotation-toggle {
    /* We don't want the annotation toggle to disturb the text layout. */
    position: absolute;
    margin: 0;
    z-index: 1;
    /* But we still need to center it relative to its parent. */
    top: 50%;
    transform: translateY(-50%);
    transition: opacity .5s ease;
  }

  .annotation-toggle.sr-only {
    opacity: 0;
  }
}

mark.annotation:not(.annotation-highlight) {
  padding: 0;
  background-color: unset;
  color: unset;
}

.annotation .annotation-bubble-tools .btn, .annotation .annotation-bubble-close .btn {
  --padding-base-horizontal: 12px;
  background: transparent;
  border: none;
  /* Align first button with the annotation text. */
  margin-left: calc(-1 * var(--padding-base-horizontal));

  /* No background to cast a shadow on, drop it (like .btn-link). */
  &:active, &.active {
    box-shadow: none;
  }
}

/* The Delete action is a form (so it submits as a real POST, not a link), but it should still sit inline with
   its sibling buttons rather than starting a new line, like a form's default block display would. */
.annotation .annotation-bubble-tools .delete-form {
  display: inline-block;
}

/* Annotation boxes */
.annotation-bubble {
  background: $theme.backgroundSecondaryColor;
  border: 1px solid $theme.borderColor;
  width: 560px;
  position: absolute;
  border-radius: 0 var(--border-radius-large) var(--border-radius-large) var(--border-radius-large);
  box-shadow: 0 2px 4px -1px;
  margin: 0 10px;
  z-index: 2;
}

.annotation-bubble:before, .annotation-bubble:after {
  content: "";
  display: block;
  position: absolute;
  border-right: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.annotation-bubble:before {
  top: -1px;
  left: -11px;
  border-right-color: $theme.borderColor;
}
.annotation-bubble:after {
  top: 0;
  left: -10px;
  border-right-color: $theme.backgroundSecondaryColor;
}

.annotation-bubble.annotation-bubble-position-left {
  border-top-left-radius: 10px;
  border-top-right-radius: 0;

  &:before, &:after {
    border-right: none;
    left: unset;
    border-left: 10px solid transparent;
    border-bottom: 10px solid transparent;
  }

  &:before {
    right: -11px;
    border-left-color: $theme.borderColor;
  }

  &:after {
    right: -10px;
    border-left-color: $theme.backgroundSecondaryColor;
  }
}

.annotation-box .annotation {
  padding: 6px 12px;
  display: grid;
  gap: .5em;
  grid-template-columns: min-content auto min-content;
  width: 100%;

  .annotation-bubble-avatar {
    grid-area: 1 / 1 / 3 / 2;
  }

  .annotation-bubble-header {
    grid-area: 1 / 2 / 2 / 3;
  }

  .annotation-bubble-close {
    grid-area: 1 / 3 / 3 / 4;
    display: flex;
    flex-direction: row-reverse;
    align-items: flex-start;
  }

  .annotation-bubble-content {
    grid-area: 2 / 2 / 3 / 4;
  }

  .annotation-bubble-tools, .annotation-bubble-edit-tools {
    grid-area: 3 / 2 / 4 / 4;
  }
}

.annotation-bubble .loading {
  height: 75px;
}

.annotation-box textarea {
  width: 99%;
}

.annotation-bubble-header {
  display: flex;
  gap: .5em;
}

.annotation-box .annotationDate {
  padding-top: 3px;
  margin-right: 51px;
  display: block;
}

.annotation-box .links {
  float: right;
  font-size: 80%;
  text-transform: lowercase;
}

#xwikicontent .annotationAdd {
  background-image: #imgURL('note_add');
}

/* Annotations list (extra-tab) */
#allAnnotations .annotation {
  margin: 0 0 8px;
  /* The gutter a comment reserves for its avatar, see .reply in comments.css. */
  padding-left: 60px;
  /* Keep the floated avatar inside its own annotation. */
  display: flow-root;

  /* Same values as .commentavatar in comments.css: a 50px avatar pulled into the 60px gutter, centered in it, and
     nudged down to sit level with the author name. */
  .annotation-bubble-avatar {
    float: left;
    margin-left: -60px;
    padding-top: 5px;
    text-align: center;
    width: 50px;
  }
}

.annotationText {
  padding: 0 36px 0 0;
  text-align: justify;
}
.annotatedText {
  font-style: italic;
  font-size: 1.2em;
  border-left: none;
  padding: 10px 0 0 0;
  margin: 0;
  /* We hide the overflow so that the decorative quote doesn't go over the rest of the UI. */
  overflow: hidden;

  &:before {
    content: "“";
    font-size: 4em;
    line-height: .1em;
    margin-right: .1em;
    vertical-align: -.45em;
    font-family: var(--font-family-serif);
    font-weight: var(--font-weight-semibold);
    font-style: normal;
  }
}

.annotationDate {
  color: $theme.textSecondaryColor;
  font-size: 80%;
}

dt.annotationLabel label {
  color: $theme.textPrimaryColor;
  font-variant: small-caps;
}

/* Quieter than the selection the annotation points at now, without the decorative quote of the live one. */
.originalAnnotatedText {
  color: var(--text-muted);
  /* Barely smaller, enough to rank it below the live selection without making it hard to read. */
  font-size: .95em;
  /* Separate it from the message introducing it. */
  padding-top: .3em;

  &:before {
    content: none;
  }
}

.annotation-bubble-content dt {
  margin: 0;
}
.annotation-bubble-content dd, .annotation-bubble-content blockquote {
  margin-bottom: 10px;
}
.annotation-bubble-content blockquote {
  padding-left: 12px;
}
